(* test/test_cli.ml -- PROVIDED. Do not edit; make the code pass. Each test id (T-nnn) is quoted in the spec. *)
open OUnit2
open Scaffold
open Test_helpers

let tests =
  "cli" >::: [
    "T-182 Cli.parse_flags: command and flags" >:: (fun _ -> (match Cli.parse_flags ["gen";"--ft";"python";"--json"] with Ok p -> assert_bool "cmd" (p.Cli.cmd = Some "gen"); assert_bool "ft" (List.assoc_opt "ft" p.Cli.flags = Some "python"); assert_bool "json" p.Cli.json | Error _ -> assert_failure "ok"));
    "T-183 Cli.parse_flags: set pairs keep order" >:: (fun _ -> (match Cli.parse_flags ["gen";"--set";"a=1";"--set";"b=2"] with Ok p -> assert_bool "set" (p.Cli.set = [("a","1");("b","2")]) | Error _ -> assert_failure "ok"));
    "T-184 Cli.parse_flags: = in value and empty value" >:: (fun _ -> (match Cli.parse_flags ["gen";"--set";"a=b=c";"--set";"d="] with Ok p -> assert_bool "set" (p.Cli.set = [("a","b=c");("d","")]) | Error _ -> assert_failure "ok"));
    "T-185 Cli.parse_flags: last repeated flag wins" >:: (fun _ -> (match Cli.parse_flags ["list";"--lang";"python";"--lang";"ocaml"] with Ok p -> assert_bool "last" (List.assoc_opt "lang" p.Cli.flags = Some "ocaml") | Error _ -> assert_failure "ok"));
    "T-186 Cli.parse_flags: empty argv" >:: (fun _ -> (match Cli.parse_flags [] with Ok p -> assert_bool "none" (p.Cli.cmd = None && p.Cli.set = [] && p.Cli.flags = [] && not p.Cli.json) | Error _ -> assert_failure "ok"));
    "T-187 Cli.parse_flags: unknown flag" >:: (fun _ -> assert_bool "u" (Cli.parse_flags ["gen";"--bogus"] = Error (Err.Unknown_flag "--bogus")));
    "T-188 Cli.parse_flags: missing value" >:: (fun _ -> assert_bool "m" (Cli.parse_flags ["gen";"--lang"] = Error (Err.Missing_value "--lang")));
    "T-189 Cli.parse_flags: bad set" >:: (fun _ -> assert_bool "b" (Cli.parse_flags ["gen";"--set";"novalue"] = Error (Err.Bad_set "novalue")); assert_bool "b2" (Cli.parse_flags ["--set";"=x"] = Error (Err.Bad_set "=x")));
    "T-190 Cli.parse_flags: second command" >:: (fun _ -> assert_bool "x" (Cli.parse_flags ["gen";"list"] = Error (Err.Unexpected_arg "list")));
    "T-191 Cli.resolve_lang: ft maps through registry" >:: (fun _ -> let regs = regs () in assert_bool "js" (Cli.resolve_lang regs [("ft","javascriptreact")] = Some "javascript"));
    "T-192 Cli.resolve_lang: lang wins" >:: (fun _ -> let regs = regs () in assert_bool "lang" (Cli.resolve_lang regs [("ft","python");("lang","ocaml")] = Some "ocaml"));
    "T-193 Cli.resolve_lang: neither" >:: (fun _ -> let regs = regs () in assert_bool "none" (Cli.resolve_lang regs [] = None));
    "T-194 Cli.resolve_lang: unmapped ft passes through" >:: (fun _ -> let regs = regs () in assert_bool "raw" (Cli.resolve_lang regs [("ft","lua")] = Some "lua"));
    "T-195 Cli.run_list: lists four" >:: (fun _ -> let regs = regs () in (match Cli.run_list regs [("lang","python")] with Ok l -> eq_int 4 (List.length l) | Error _ -> assert_failure "ok"));
    "T-196 Cli.run_list: ft works" >:: (fun _ -> let regs = regs () in (match Cli.run_list regs [("ft","javascriptreact")] with Ok l -> eq_int 4 (List.length l) | Error _ -> assert_failure "ok"));
    "T-197 Cli.run_list: missing language" >:: (fun _ -> let regs = regs () in assert_bool "e" (Cli.run_list regs [] = Error (Err.Unknown_lang "")));
    "T-198 Cli.run_prompts: stack in javascript" >:: (fun _ -> let regs = regs () in (match Cli.run_prompts regs [("ft","javascript");("algo","stack")] with Ok ps -> eq_strs ["type_name=Stack";"elem=int"] (List.map (fun ((p : Catalog.param), g) -> p.name ^ "=" ^ g) ps) | Error _ -> assert_failure "ok"));
    "T-199 Cli.run_prompts: unknown algo" >:: (fun _ -> let regs = regs () in assert_bool "a" (Result.is_error (Cli.run_prompts regs [("lang","python");("algo","zzz")])); is_err "unknown_algo" (Cli.run_prompts regs [("lang","python");("algo","zzz")]));
    "T-200 Cli.run_prompts: language first" >:: (fun _ -> let regs = regs () in is_err "unknown_lang" (Cli.run_prompts regs [("lang","cobol");("algo","zzz")]));
    "T-201 Cli.run_gen: default gen" >:: (fun _ -> let regs = regs () in (match Cli.run_gen regs [("lang","python");("algo","stack")] [] with Ok p -> assert_bool "text" (contains p.Insert.text "class Stack") | Error _ -> assert_failure "ok"));
    "T-202 Cli.run_gen: --set answers" >:: (fun _ -> let regs = regs () in (match Cli.run_gen regs [("lang","python");("algo","stack")] [("type_name","my stack");("elem","bool")] with Ok p -> assert_bool "text" (contains p.Insert.text "class MyStack") | Error _ -> assert_failure "ok"));
    "T-203 Cli.run_gen: --scan avoids a clash" >:: (fun _ -> let regs = regs () in (match Cli.run_gen regs [("lang","python");("algo","binary-search");("scan","def binary_search(): pass")] [] with Ok p -> assert_bool "suffix" (contains p.Insert.text "def binary_search_2(") | Error _ -> assert_failure "ok"));
    "T-204 Cli.run_gen: --existing is split on commas, empties ignored" >:: (fun _ -> let regs = regs () in (match Cli.run_gen regs [("lang","python");("algo","binary-search");("existing",",binary_search,")] [] with Ok p -> assert_bool "suffix" (contains p.Insert.text "def binary_search_2(") | Error _ -> assert_failure "ok"));
    "T-205 Cli.run_gen: --scan wins over --existing" >:: (fun _ -> let regs = regs () in (match Cli.run_gen regs [("lang","python");("algo","binary-search");("scan","x = 1");("existing","binary_search")] [] with Ok p -> assert_bool "no suffix" (contains p.Insert.text "def binary_search(") | Error _ -> assert_failure "ok"));
    "T-206 Cli.run_gen: cursor indent" >:: (fun _ -> let regs = regs () in (match Cli.run_gen regs [("lang","python");("algo","union-find");("indent","4")] [] with Ok p -> eq_str "    " (String.sub p.Insert.text 0 4) | Error _ -> assert_failure "ok"));
    "T-207 Cli.run_gen: file mode" >:: (fun _ -> let regs = regs () in (match Cli.run_gen regs [("lang","javascript");("algo","binary-search");("mode","file")] [] with Ok p -> assert_bool "file" (p.Insert.file = Some "binarySearch.js") | Error _ -> assert_failure "ok"));
    "T-208 Cli.run_gen: bad mode" >:: (fun _ -> let regs = regs () in assert_bool "m" (Cli.run_gen regs [("lang","python");("algo","stack");("mode","zzz")] [] = Error (Err.Bad_value { flag = "--mode"; value = "zzz" })));
    "T-209 Cli.run_gen: bad indent" >:: (fun _ -> let regs = regs () in assert_bool "i" (Cli.run_gen regs [("lang","python");("algo","stack");("indent","-3")] [] = Error (Err.Bad_value { flag = "--indent"; value = "-3" })); is_err "bad_value" (Cli.run_gen regs [("lang","python");("algo","stack");("indent","x")] []));
    "T-210 Cli.run_gen: validation before lookup" >:: (fun _ -> let regs = regs () in is_err "bad_value" (Cli.run_gen regs [("lang","cobol");("mode","zzz")] []));
    "T-211 Cli.run_gen: engine errors pass through" >:: (fun _ -> let regs = regs () in is_err "unknown_lang" (Cli.run_gen regs [("lang","cobol");("algo","stack")] []); is_err "unknown_param" (Cli.run_gen regs [("lang","python");("algo","stack")] [("zzz","1")]));
    "T-212 Cli.run_ask: uses answers" >:: (fun _ -> let regs = regs () in (match Cli.run_ask regs [("lang","python");("algo","stack")] ~ask:(fun ~prompt ~ghost:_ -> if contains prompt "Type" then Some "my stack" else Some "bool") with Ok (Some p) -> assert_bool "cls" (contains p.Insert.text "class MyStack") | _ -> assert_failure "expected a plan"));
    "T-213 Cli.run_ask: ghost is offered, accepting it uses the default" >:: (fun _ -> let regs = regs () in (match Cli.run_ask regs [("lang","python");("algo","stack")] ~ask:(fun ~prompt:_ ~ghost -> Some ghost) with Ok (Some p) -> assert_bool "cls" (contains p.Insert.text "class Stack") | _ -> assert_failure "expected a plan"));
    "T-214 Cli.run_ask: questions in parameter order" >:: (fun _ -> let regs = regs () in let seen = ref [] in ignore (Cli.run_ask regs [("lang","python");("algo","stack")] ~ask:(fun ~prompt ~ghost -> seen := prompt :: !seen; Some ghost)); eq_int 2 (List.length !seen); assert_bool "first" (contains (List.nth (List.rev !seen) 0) "Type name"));
    "T-215 Cli.run_ask: cancel stops asking" >:: (fun _ -> let regs = regs () in let n = ref 0 in let r = Cli.run_ask regs [("lang","python");("algo","stack")] ~ask:(fun ~prompt:_ ~ghost:_ -> incr n; None) in assert_bool "none" (r = Ok None); eq_int 1 !n);
    "T-216 Cli.run_ask: unknown language; ask not called" >:: (fun _ -> let regs = regs () in let n = ref 0 in let r = Cli.run_ask regs [("lang","cobol");("algo","stack")] ~ask:(fun ~prompt:_ ~ghost:_ -> incr n; None) in assert_bool "e" (Result.is_error r); eq_int 0 !n);
    "T-217 Cli.run_ask: bad answer surfaces as an error" >:: (fun _ -> let regs = regs () in is_err "bad_elem" (Cli.run_ask regs [("lang","python");("algo","stack")] ~ask:(fun ~prompt ~ghost:_ -> if contains prompt "Element" then Some "double" else Some "")));
    "T-218 Cli.run: list text" >:: (fun _ -> let o = Cli.run ["list";"--lang";"ocaml"] in eq_int 0 o.Cli.code; assert_bool "line" (contains o.Cli.stdout "binary-search\tBinary search"); eq_str "" o.Cli.stderr);
    "T-219 Cli.run: list json" >:: (fun _ -> let o = Cli.run ["list";"--lang";"ocaml";"--json"] in eq_int 0 o.Cli.code; assert_bool "json" (contains o.Cli.stdout "{\"items\":[{\"id\":\"binary-search\",\"title\":\"Binary search\",\"group\":\"searching\"}"));
    "T-220 Cli.run: prompts json" >:: (fun _ -> let o = Cli.run ["prompts";"--lang";"python";"--algo";"stack";"--json"] in eq_int 0 o.Cli.code; assert_bool "json" (contains o.Cli.stdout "{\"prompts\":[{\"name\":\"type_name\",\"prompt\":\"Type name\",\"ghost\":\"Stack\"}"));
    "T-221 Cli.run: prompts text" >:: (fun _ -> let o = Cli.run ["prompts";"--lang";"python";"--algo";"stack"] in assert_bool "line" (contains o.Cli.stdout "type_name\tType name\tStack"));
    "T-222 Cli.run: gen text is the code" >:: (fun _ -> let o = Cli.run ["gen";"--lang";"python";"--algo";"union-find"] in eq_int 0 o.Cli.code; assert_bool "class" (contains o.Cli.stdout "class UnionFind"));
    "T-223 Cli.run: gen json has text and null file" >:: (fun _ -> let o = Cli.run ["gen";"--lang";"python";"--algo";"union-find";"--json"] in assert_bool "text" (contains o.Cli.stdout "{\"text\":\""); assert_bool "null" (contains o.Cli.stdout "\"file\":null}"));
    "T-224 Cli.run: gen json file mode names the file" >:: (fun _ -> let o = Cli.run ["gen";"--lang";"javascript";"--algo";"stack";"--mode";"file";"--json"] in assert_bool "file" (contains o.Cli.stdout "\"file\":\"stack.js\"}"));
    "T-225 Cli.run: stdin only for --scan -" >:: (fun _ -> let calls = ref 0 in ignore (Cli.run ~stdin:(fun () -> incr calls; "") ["list";"--lang";"python"]); eq_int 0 !calls; ignore (Cli.run ~stdin:(fun () -> incr calls; "") ["gen";"--lang";"python";"--algo";"stack";"--scan";"-"]); eq_int 1 !calls);
    "T-226 Cli.run: scan text from stdin avoids a clash" >:: (fun _ -> let o = Cli.run ~stdin:(fun () -> "def binary_search(): pass") ["gen";"--lang";"python";"--algo";"binary-search";"--scan";"-"] in assert_bool "suffix" (contains o.Cli.stdout "def binary_search_2("));
    "T-227 Cli.run: scan text given directly" >:: (fun _ -> let o = Cli.run ["gen";"--lang";"python";"--algo";"binary-search";"--scan";"def binary_search(): pass"] in assert_bool "suffix" (contains o.Cli.stdout "binary_search_2"));
    "T-228 Cli.run: --ft works like --lang" >:: (fun _ -> let o = Cli.run ["list";"--ft";"javascriptreact"] in eq_int 0 o.Cli.code);
    "T-229 Cli.run: domain error: text mode" >:: (fun _ -> let o = Cli.run ["list";"--lang";"cobol"] in eq_int 1 o.Cli.code; eq_str "" o.Cli.stdout; eq_str "unknown language: cobol" o.Cli.stderr);
    "T-230 Cli.run: domain error: JSON mode" >:: (fun _ -> let o = Cli.run ["list";"--lang";"cobol";"--json"] in eq_int 1 o.Cli.code; eq_str "" o.Cli.stderr; eq_str "{\"error\":{\"code\":\"unknown_lang\",\"message\":\"unknown language: cobol\"}}" o.Cli.stdout);
    "T-231 Cli.run: usage error" >:: (fun _ -> let o = Cli.run ["gen";"--bogus"] in eq_int 2 o.Cli.code; eq_str "usage error: unknown flag: --bogus" o.Cli.stderr);
    "T-232 Cli.run: usage error in JSON mode" >:: (fun _ -> let o = Cli.run ["gen";"--bogus";"--json"] in eq_int 2 o.Cli.code; assert_bool "code" (contains o.Cli.stdout "\"code\":\"unknown_flag\""));
    "T-233 Cli.run: bad mode is a usage error" >:: (fun _ -> eq_int 2 (Cli.run ["gen";"--lang";"python";"--algo";"stack";"--mode";"zzz"]).Cli.code);
    "T-234 Cli.run: unknown command and no command" >:: (fun _ -> let o = Cli.run ["zzz"] in eq_int 2 o.Cli.code; eq_str "usage error: unknown command: zzz" o.Cli.stderr; eq_str "usage error: unknown command" (Cli.run []).Cli.stderr);
    "T-235 Cli.run: ask needs a callback" >:: (fun _ -> let o = Cli.run ["ask";"--lang";"python";"--algo";"stack"] in eq_int 2 o.Cli.code; eq_str "usage error: unknown command: ask" o.Cli.stderr);
    "T-236 Cli.run: ask with a callback" >:: (fun _ -> let o = Cli.run ~ask:(fun ~prompt:_ ~ghost -> Some ghost) ["ask";"--lang";"python";"--algo";"stack"] in eq_int 0 o.Cli.code; assert_bool "class" (contains o.Cli.stdout "class Stack"));
    "T-237 Cli.run: ask cancelled" >:: (fun _ -> let o = Cli.run ~ask:(fun ~prompt:_ ~ghost:_ -> None) ["ask";"--lang";"python";"--algo";"stack"] in eq_int 1 o.Cli.code; eq_str "cancelled" o.Cli.stderr; eq_str "" o.Cli.stdout);
    "T-238 Cli.run: exit 0 never has stderr" >:: (fun _ -> List.iter (fun argv -> let o = Cli.run argv in if o.Cli.code = 0 then eq_str "" o.Cli.stderr) [["list";"--lang";"python"];["prompts";"--lang";"ocaml";"--algo";"stack"];["gen";"--lang";"ocaml";"--algo";"stack"]]);
  ]
